          "quote": "\"supports_reload\": true, \"config_rules\": [{\"key\": \"cache_ttl_seconds\", \"type\": \"integer\", \"min\": 1, \"max\": 3600}, {\"key\": \"worker_connections\", \"type\": \"integer\", \"min\": 1, \"max\": 65535, \"restart_required\": true}]"
